package com.smartgrading.backend.controller;
import com.smartgrading.backend.dto.*; import com.smartgrading.backend.service.SubjectService; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/subjects") public class SubjectController { private final SubjectService service; public SubjectController(SubjectService s){service=s;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public SubjectResponse create(@Valid @RequestBody SubjectRequest r){return service.create(r);} @GetMapping public List<SubjectResponse> all(){return service.findAll();} @GetMapping("/{id}") public SubjectResponse one(@PathVariable Integer id){return service.find(id);} @PutMapping("/{id}") public SubjectResponse update(@PathVariable Integer id,@Valid @RequestBody SubjectRequest r){return service.update(id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Integer id){service.delete(id);} }
